const (
	maxSyscallFilterInstructions = 1 << 15
	uncacheableBPFAction = linux.SECCOMP_RET_ACTION_FULL // Sentinel value for uncachable syscall actions
)

type taskSeccomp struct {
	filters []bpf.Program
	cache   [sentry.MaxSyscallNum + 1]linux.BPFAction
	cacheAuditNumber uint32
}

// copy creates and returns a deep copy of the current `taskSeccomp`.
func (ts *taskSeccomp) copy() *taskSeccomp {
	copiedFilters := append([]bpf.Program(nil), ts.filters...) // Shallow copy of filters
	return &taskSeccomp{
		filters: copiedFilters,
		cacheAuditNumber: ts.cacheAuditNumber,
		cache: ts.cache,
	}
}

// dataAsBPFInput serializes the provided seccomp data for BPF input.
func dataAsBPFInput(t *Task, d *linux.SeccompData) bpf.Input {
	buffer := t.CopyScratchBuffer(d.SizeBytes())
	d.MarshalUnsafe(buffer)
	return buffer[:d.SizeBytes()]
}

// seccompSiginfo constructs a signal info for seccomp violations.
func seccompSiginfo(t *Task, errno, sysno int32, ip hostarch.Addr) *linux.SignalInfo {
	si := &linux.SignalInfo{
		Signo: int32(linux.SIGSYS),
		Errno: errno,
		Code:  linux.SYS_SECCOMP,
	}
	si.SetCallAddr(uint64(ip))
	si.SetSyscall(sysno)
	si.SetArch(t.SyscallTable().AuditNumber)
	return si
}

// checkSeccompSyscall evaluates seccomp filters for the syscall.
func (t *Task) checkSeccompSyscall(sysno int32, args arch.SyscallArguments, ip hostarch.Addr) linux.BPFAction {
	action := linux.BPFAction(t.evaluateSyscallFilters(sysno, args, ip))
	switch action & linux.SECCOMP_RET_ACTION {
	case linux.SECCOMP_RET_TRAP:
		t.SendSignal(seccompSiginfo(t, int32(action.Data()), sysno, ip))
		t.Arch().SetReturn(uintptr(sysno))
	case linux.SECCOMP_RET_ERRNO:
		t.Arch().SetReturn(-uintptr(action.Data()))
	case linux.SECCOMP_RET_TRACE:
		if !t.ptraceSeccomp(action.Data()) {
			t.Arch().SetReturn(-uintptr(unix.ENOSYS))
			return linux.SECCOMP_RET_ERRNO
		}
	case linux.SECCOMP_RET_ALLOW:
		// Execute the syscall
	case linux.SECCOMP_RET_KILL_THREAD:
		return linux.SECCOMP_RET_KILL_THREAD
	default:
		return linux.SECCOMP_RET_KILL_THREAD
	}
	return action
}

// evaluateSyscallFilters evaluates seccomp filters for a syscall.
func (t *Task) evaluateSyscallFilters(sysno int32, args arch.SyscallArguments, ip hostarch.Addr) uint32 {
